/* =====================================================================================
   PULSE - a live markets dashboard. p0pc0rn skeleton "dashboard-live" (p0pc0rn Kit v1.3).
   Serves: crypto prices (live from CoinGecko through p0.fetch) and any numbers the person
           gives (savings, scores): for those, leave cg out and set live_stats false.

   SCREENS
     Markets  - large title that collapses on scroll. A hero card: the value that rolls
                (K.count), a green / red change chip, a LIVE dot with "Updated HH:MM:SS", a
                chart of real prices that draws itself on and a 1D / 1W / 1M / 1Y range
                control. Then WATCHLIST and MORE MARKETS rows with mini sparklines and a
                MARKET grid of stat cards. Pull the page down to refresh. Gear -> Settings.
     Detail   - opened from a row with a 'slide'. Big price, the change for the range, a chart
                you can scrub (hold, or drag sideways; a tap pins a point), a 2 x 3 stat grid
                (market cap, volume, 24 h high / low, all-time high, supply), About and a
                price alert. The star adds / removes the market from the watchlist.
     Sheets   - Settings (live updates, simulate offline, show change as % or $) and
                Price alert (slider, save, remove).
   REAL DATA ONLY: every price, line and stat is CoinGecko's own (or the person's own numbers
   for an item without a coin id). CoinGecko's free feed has about 7 days of hourly prices, so
   1D and 1W draw real lines; 1M and 1Y show the real change with no line. A coin shows "-"
   until its first live price. Nothing is made up to fill a gap, and nothing here is advice.
   STATES: loading (shimmer on launch and during a pull-refresh), error (offline banner with
   Retry + red toast), empty watchlist (K.empty), live ticks (prices roll and flash), a price
   alert (a toast with a bell).
   ===================================================================================== */

// ===== THEME + LAYOUT =====
const ACCENT = (window.SLOTS && window.SLOTS.accent) || '#2e8bff';      // REPLACE: electric blue - buttons, LIVE dot, spinner, scrub ring
const NAVY = '#060c1a';        // page background (dark navy)
const GAIN = '#22d38a';        // green = went up
const LOSS = '#ff5468';        // red = went down
const GOLD = '#ffc94d';        // watchlist star, alert bell
const SIDE = 16;               // screen margin: cards sit 16 px in from each edge
const GAP = 12;                // gap between grid cards
const ROW_H = 68;              // watchlist row height
const STAT_H = 96;             // stat card height
const PULL_T = 64;             // pull this far past the top (px) to arm a refresh
const PULL_HOLD = 56;          // while refreshing, the page stays this far down (room for the spinner)
const LIVE_EVERY_S = 60;       // seconds between quiet live ticks (the host caches prices for a minute)
const LATENCY = { boot: 900, pull: 1800, tick: 0 };   // no live source: a short pause, so a pull still shows its spinner
const STORE_KEY = 'pulse-markets:v1';                   // REPLACE: one storage key per app
const DAY_MS = 86400000;
const RANGES = [
  { key: 'D', label: '1D', caption: 'Past 24 hours', span: DAY_MS },
  { key: 'W', label: '1W', caption: 'Past week', span: 7 * DAY_MS },
  { key: 'M', label: '1M', caption: 'Past month', span: 30 * DAY_MS },
  { key: 'Y', label: '1Y', caption: 'Past year', span: 365 * DAY_MS }
];

// ===== FALLBACK (only if the slots have no items): two coins and nothing else; every number comes from the live feed =====
const DEF_ITEMS = [
  { sym: 'AVAX', name: 'Avalanche', kind: 'Crypto', color: '#e84142', cg: 'avalanche-2',
    about: 'A fast, low-fee smart-contract platform: a primary network plus custom Layer 1 chains that each set their own rules.' },
  { sym: 'BTC', name: 'Bitcoin', kind: 'Crypto', color: '#f7931a', cg: 'bitcoin',
    about: 'The first cryptocurrency: a fixed supply of 21 million coins, secured by proof-of-work mining since 2009.' }
];
// the 4 tiles while the first coin's live facts are on their way (live_stats)
const WAIT_STATS = (a) => [
  { label: a.sym + ' RANK', value: '–', sub: 'by market cap', tone: '', icon: 'trophy' },
  { label: 'MARKET CAP', value: '–', sub: a.name.slice(0, 22), tone: '', icon: 'globe' },
  { label: '24H VOLUME', value: '–', sub: 'traded in 24 h', tone: '', icon: 'bolt' },
  { label: 'SUPPLY', value: '–', sub: 'in circulation', tone: '', icon: 'coin' }
];

const okIcon = (n, d) => (typeof n === 'string' && (!K.ICONS || K.ICONS.includes(n)) ? n : d);
// ----- slots -----
const SL = window.SLOTS || {};
const CUR = typeof SL.currency === 'string' ? SL.currency.slice(0, 3) : '$';
const PAGE_TITLE = String(SL.title || 'Markets').slice(0, 22);
const fin = (v) => (v == null || v === '' || !Number.isFinite(+v) ? null : +v);   // a number, or null when there is none (never a made-up 0)
// A coin (cg) takes every number from the live feed: whatever its slots say is never shown. Anything else shows the person's own numbers.
const ASSETS = (Array.isArray(SL.items) && SL.items.length ? SL.items : DEF_ITEMS).slice(0, 12).map((a, i) => {
  const sym = String(a.sym || a.symbol || a.name || 'I' + i).toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 5) || 'I' + i, c = a.chg || {};
  const cg = /^[a-z0-9-]{2,60}$/.test(String(a.cg || '')) ? String(a.cg) : '', own = !cg && fin(a.price ?? a.value) != null;
  return { sym, name: String(a.name || sym).slice(0, 28), kind: String(a.kind || 'Item').slice(0, 14), glyph: String(a.glyph || sym[0]).slice(0, 2),
    color: a.color || '#8c9bff', cg, held: Math.max(0, fin(a.held) || 0), known: own, price: own ? fin(a.price ?? a.value) : null,
    chg: own ? { D: fin(c.D), W: fin(c.W), M: fin(c.M), Y: fin(c.Y) } : { D: null, W: null, M: null, Y: null },
    cap: null, volume: null, supply: null, high: null, low: null, ath: null, spark: null, at: 0, coin: null, capNote: '', about: String(a.about || '').slice(0, 220) };
});
// nothing held: the hero shows the FIRST item's own price (a watchlist, not a portfolio)
if (!ASSETS.some((a) => a.held > 0)) ASSETS[0].held = 1;
const HERO_LABEL = String(SL.hero_label || (ASSETS.filter((a) => a.held > 0).length > 1 ? 'TOTAL VALUE' : ASSETS[0].sym + ' PRICE')).toUpperCase().slice(0, 22);
const LIVE_STATS = SL.live_stats !== false;   // the 4 tiles show the first coin's live facts
const MARKET_STATS = LIVE_STATS && ASSETS[0].cg ? WAIT_STATS(ASSETS[0]) : Array.isArray(SL.stats) && SL.stats.length ? SL.stats.slice(0, 4).map((t) => ({ label: String(t.label || '').toUpperCase().slice(0, 16),
  value: String(t.value ?? '').slice(0, 10), sub: String(t.sub || '').slice(0, 22), tone: t.tone === 'up' || t.tone === 'down' ? t.tone : '', icon: okIcon(t.icon, 'chart') })) : WAIT_STATS(ASSETS[0]);

// ===== STATE =====
// prefs = what the user chose (saved). app = what is happening right now (not saved).
let prefs = { watch: ASSETS.slice(0, 4).map((a) => a.sym), range: 0, live: true, showAmount: false, alerts: {} };
const app = {
  loaded: false, refreshing: false, mode: '', error: null, errorKick: -9, offline: false,
  updatedAt: 0, bootAt: 0, dataAt: 0, chartAt: 0, lastTick: 0, pullArmed: false, pullDrop: 0,
  sheet: null, sym: ASSETS[0].sym, homeY: 0, homeH: 1200, detailY: 0, detailH: 1200,
  scrubId: null, scrubI: -1, pinI: -1, alertDraft: 0.05, starSpring: null
};

// ===== SETUP + FRAME =====
function setup() {
  K.setup({ mode: 'dark', accent: ACCENT, bg: NAVY, good: GAIN, bad: LOSS,
    surface: '#0e1729', surface2: '#15203a', surface3: '#1d2a48' });   // navy cards; 2 + 3 given (derived ones are greyer)
  restore();
  ASSETS.forEach(buildSeries);
  app.bootAt = K.t;
  app.starSpring = K.spring(1, { k: 320, d: 12 });
  K.count('hero', 0, 1);                  // WHY: seed at 0 so the first real total rolls up from zero
  K.scene('home', drawHome);
  K.scene('detail', drawDetail);
  refreshData('boot');
}

function draw() {
  K.render();
  // Quiet live ticks: the same refresh path, no spinner and no toast unless something breaks.
  if (prefs.live && app.loaded && !app.refreshing && K.t - app.lastTick > LIVE_EVERY_S) refreshData('tick');
}

// ===== STORAGE =====
function restore() {
  const saved = K.load(STORE_KEY, null);
  if (!saved) return;
  prefs = Object.assign(prefs, saved.prefs || {});
  // the last live answer (with its time) shows until the next one; prices saved by older versions of this app are not used
  const L = saved.live;
  if (L && L.coins && L.at) { for (const a of ASSETS) if (a.cg && L.coins[a.cg]) applyCoin(a, L.coins[a.cg], L.at); app.updatedAt = L.at; }
}

// Saves choices and the last live answer, so a relaunch shows real numbers (marked with their time) before the first refresh.
// WHY app.offline is not saved: it is a test switch; it must never survive a relaunch.
function persist() {
  const coins = {};
  for (const a of ASSETS) if (a.cg && a.coin) coins[a.cg] = a.coin;
  K.save(STORE_KEY, { prefs, live: app.updatedAt && Object.keys(coins).length ? { at: app.updatedAt, coins } : null });
}

// ===== SERIES (real points only) =====
// a.series[key] = the values a range draws, a.times[key] = when each one was (ms). With CoinGecko's ~hourly 7-day prices, 1D and 1W are
// real lines. Otherwise a range has just two real values, its start (from its % change) and now, and no line is drawn between them.
// null = nothing known for that range.
const lined = (v) => !!v && v.length > 2;
function buildSeries(a) {
  a.series = {}; a.times = {};
  if (a.flashAt == null) a.flashAt = -9;
  for (const r of RANGES) {
    a.series[r.key] = null; a.times[r.key] = null;
    if (!a.known) continue;
    const pts = a.spark && (r.key === 'D' || r.key === 'W') ? sparkPoints(a, r.span) : null;
    if (pts) { a.series[r.key] = pts.v; a.times[r.key] = pts.t; continue; }
    const c = a.chg[r.key];
    if (c != null && c > -100) a.series[r.key] = [a.price / (1 + c / 100), a.price];
  }
}

// CoinGecko's sparkline: its last 7 days, evenly spaced, oldest first, ending about when it answered; the live price is the newest point.
function sparkPoints(a, span) {
  const n = a.spark.length; if (n < 3) return null;
  const step = 7 * DAY_MS / n, v = [], t = [];
  for (let i = 0; i < n; i++) { const ts = a.at - (n - i) * step; if (ts >= a.at - span - 1) { v.push(a.spark[i]); t.push(ts); } }
  v.push(a.price); t.push(a.at);
  return v.length > 2 ? { v, t } : null;
}

// The hero's line: the sum of every holding, point by point, only when all of them have the same real points; else just start and now.
function portfolioSeries(key) {
  const held = ASSETS.filter((a) => a.held > 0);
  if (!held.length || held.some((a) => !a.series[key])) return null;
  const n = held[0].series[key].length;
  if (n > 2 && held.every((a) => a.series[key].length === n)) {
    const out = new Array(n).fill(0);
    for (const a of held) a.series[key].forEach((v, i) => { out[i] += v * a.held; });
    return out;
  }
  let s0 = 0, s1 = 0;
  for (const a of held) { const v = a.series[key]; s0 += v[0] * a.held; s1 += v[v.length - 1] * a.held; }
  return [s0, s1];
}

// Change from the first point of the series to point i (default: the last point).
function seriesDelta(series, i) {
  const end = series[i == null ? series.length - 1 : i], abs = end - series[0];
  return { abs, pct: (abs / series[0]) * 100 };
}

// What a chart says when it has no line: why, in a few words.
function noLine(list, key) {
  if (list.some((a) => !a.known)) return 'Waiting for prices';
  if (list.every((a) => a.cg)) return key === 'D' || key === 'W' ? 'No price line from CoinGecko right now' : 'A line for 1D and 1W only';
  return 'Only the change is known';
}

// ===== LIVE DATA =====
// fetchLive() resolves to { at, coins: { <CoinGecko id>: coin } } or null (no coin ids here). Only CoinGecko's own numbers, through the host.
async function fetchLive() {
  const ids = ASSETS.map((a) => a.cg).filter(Boolean);
  if (!ids.length || !window.p0) return null;
  const d = await p0.fetch('prices.coingecko', { ids }), coins = {};
  for (const c of d.coins || []) if (c && c.id && fin(c.price) != null) coins[c.id] = c;
  return { at: d.fetchedAt || Date.now(), coins };
}

// One coin's live record onto its item (also the saved one at launch).
function applyCoin(a, c, at) {
  const g = c.chg || {};
  a.coin = c; a.known = true; a.at = at; a.price = fin(c.price);
  a.chg = { D: fin(g.D), W: fin(g.W), M: fin(g.M), Y: fin(g.Y) };
  a.cap = fin(c.cap); a.volume = fin(c.volume); a.supply = fin(c.supply); a.high = fin(c.high); a.low = fin(c.low); a.ath = fin(c.ath);
  a.spark = Array.isArray(c.spark) ? c.spark.map(fin).filter((v) => v != null) : null;
  a.capNote = fin(c.rank) ? 'Rank #' + c.rank : '';
  buildSeries(a);
}

// One path for every refresh. mode 'boot' = launch (shimmer), 'pull' = pull-to-refresh or Retry
// (spinner + shimmer + toast), 'tick' = a silent live update.
async function refreshData(mode) {
  if (app.refreshing) return;
  app.refreshing = true;
  app.mode = mode;
  app.lastTick = K.t;
  if (mode === 'pull') K.sfx('whoosh');
  let live = null, failure = null;
  try {
    live = await fetchLive();
    if (!live) await wait(LATENCY[mode]);
    if (app.offline) throw new Error('No connection');   // the Settings "Simulate offline" switch
  } catch (err) {
    failure = err;
  }
  app.refreshing = false;
  if (failure) onRefreshFailed(mode, failure);
  else onRefreshed(mode, live);
  if (!app.loaded) { app.loaded = true; app.dataAt = K.t; app.chartAt = K.t; }
}

function wait(ms) { return new Promise(done => setTimeout(done, ms)); }

function onRefreshed(mode, live) {
  const wasOffline = !!app.error;
  for (const a of ASSETS) {
    const c = live && a.cg ? live.coins[a.cg] : null;
    if (!c) continue;                     // no new live price: the item keeps what it had
    const before = a.known ? a.price : null;
    applyCoin(a, c, live.at);
    if (before != null && a.price !== before) {
      a.flashAt = K.t;                    // row price flashes green / red for a moment
      a.flashUp = a.price > before;
      checkAlerts(a, before);
    }
  }
  app.error = null;
  app.live = !!live && Object.keys(live.coins).length > 0;
  if (app.live) app.updatedAt = live.at;
  const f = ASSETS[0];
  if (app.live && LIVE_STATS && f.cg && f.coin) {
    MARKET_STATS.splice(0, 4, { label: f.sym + ' RANK', value: fin(f.coin.rank) ? '#' + f.coin.rank : '–', sub: 'by market cap', tone: '', icon: 'trophy' },
      { label: 'MARKET CAP', value: f.cap ? compactMoney(f.cap) : '–', sub: f.name.slice(0, 22), tone: '', icon: 'globe' },
      { label: '24H VOLUME', value: f.volume ? compactMoney(f.volume) : '–', sub: 'traded in 24 h', tone: '', icon: 'bolt' },
      { label: 'SUPPLY', value: f.supply ? K.fmt.compact(f.supply) : '–', sub: 'in circulation', tone: '', icon: 'coin' });
  }
  if (mode === 'pull') {
    app.dataAt = K.t;                     // re-run the row entrance: fresh data slides in
    K.sfx('success');
    K.toast(app.live ? (wasOffline ? 'Back online - prices updated' : 'Prices updated') : ASSETS.some((a) => a.cg) ? 'No live prices right now' : 'Nothing live to refresh',
      { tone: app.live ? 'good' : 'info' });
  } else if (wasOffline) {
    K.toast('Back online', { tone: 'good' });
  }
  persist();
}

function onRefreshFailed(mode, err) {
  const first = !app.error;
  app.error = { msg: String((err && err.message) || err), at: Date.now() };
  app.errorKick = K.t;                    // the offline banner shakes once
  if (mode !== 'tick' || first) {         // WHY: silent ticks only speak up the first time
    K.sfx('error');
    K.toast('Couldn\'t refresh prices', { tone: 'bad', ms: 3200 });   // errors stay up longer
  }
}

// A price alert fires once when the live price crosses its target (either direction), then clears. Information, not a celebration.
function checkAlerts(a, before) {
  const target = prefs.alerts[a.sym];
  if (!target || before == null || (before - target) * (a.price - target) > 0) return;
  delete prefs.alerts[a.sym];
  K.sfx('pop');
  K.toast(a.sym + ' crossed ' + K.fmt.money(target, CUR, dp(target)), { tone: 'info', icon: 'bell', ms: 3200 });
}

// ===== PULL TO REFRESH =====
// K.scroll rubber-bands below 0 when the page is pulled down at the top. Past PULL_T we arm (tick),
// on release we refresh. Returns the scroll value to draw with: while a pull-refresh runs the page
// stays PULL_HOLD px down so the spinner has room (feed it to the content AND to K.navBar).
function pullToRefresh(scrollY) {
  const pull = Math.max(0, -scrollY);
  if (K.ptr.down && pull > PULL_T && !app.pullArmed && !app.refreshing) { app.pullArmed = true; K.sfx('tick'); }
  if (K.ptr.down && app.pullArmed && pull < PULL_T * 0.5) app.pullArmed = false;   // pushed back up = cancel
  if (!K.ptr.down && app.pullArmed) { app.pullArmed = false; refreshData('pull'); }
  const hold = K.anim('pullHold', app.refreshing && app.mode === 'pull' ? PULL_HOLD : 0, 12);
  app.pullDrop = Math.max(pull, hold);
  return scrollY >= 0 ? scrollY - hold : -app.pullDrop;
}

// iOS-style activity indicator: 8 spokes appear one by one while pulling, then rotate while loading.
function drawSpinner(drop) {
  const spinning = app.refreshing && app.mode === 'pull';
  if (drop < 4 || (!spinning && !K.ptr.down)) return;   // hidden while the page settles back up
  const cx = K.W / 2, cy = K.safe.top + 50 + drop / 2;
  const shown = spinning ? 8 : Math.floor(K.clamp(drop / PULL_T, 0, 1) * 8);
  const head = Math.floor(K.t * 12) % 8;
  for (let i = 0; i < shown; i++) {
    const ang = -Math.PI / 2 + (i / 8) * Math.PI * 2;
    const fade = spinning ? 1 - (((head - i) + 8) % 8) / 8 * 0.8 : 0.75;
    K.line(cx + Math.cos(ang) * 5.5, cy + Math.sin(ang) * 5.5, cx + Math.cos(ang) * 11, cy + Math.sin(ang) * 11,
      K.alpha(K.C.text, fade), 2.6);
  }
}

// ===== SCREEN: MARKETS (home) =====
// No sheet checks on the page: an open K.sheet makes everything drawn outside it inert (kit v1.1), K.scroll included.
function drawHome() {
  const ds = portfolioSeries('D'), dayUp = !ds || seriesDelta(ds).abs >= 0, sub = todayLabel();
  K.backdrop({ top: '#0b1630', bottom: '#050a15', vignette: 0.4, grain: 0.04, glow: [
    { x: K.W * 0.92, y: 20, r: 360, color: ACCENT, s: 0.2 },
    { x: K.W * 0.08, y: 420, r: 320, color: dayUp ? GAIN : LOSS, s: 0.07 }] });   // the page glows with the day
  app.homeY = K.scroll('home', 0, 0, K.W, K.H, app.homeH);
  const viewY = pullToRefresh(app.homeY);
  const watched = ASSETS.filter(a => prefs.watch.includes(a.sym));
  const others = ASSETS.filter(a => !prefs.watch.includes(a.sym));
  pageClip(() => {
    let y = K.navBar.top(sub) - viewY;             // known before the bar draws: no first-frame jump
    y = drawErrorBanner(SIDE, y, K.W - 2 * SIDE);
    y = drawHeroCard(SIDE, y, K.W - 2 * SIDE) + 28;
    y = drawAssetSection('WATCHLIST', watched, y, 1) + 28;
    if (others.length) y = drawAssetSection('MORE MARKETS', others, y, 2) + 28;
    const liveTiles = LIVE_STATS && ASSETS[0].cg;
    y = sectionLabel('MARKET', !liveTiles ? '' : app.live ? 'by CoinGecko' : app.updatedAt ? 'from ' + stamp(app.updatedAt) : 'waiting for prices', y);
    y = drawStatGrid(MARKET_STATS, SIDE, y, K.W - 2 * SIDE, i => K.since(app.bootAt, (i + 3) * 70, 500), busy()) + 24;
    K.text(ASSETS.some((a) => a.cg) ? 'Prices by CoinGecko. Pull down to refresh.' : 'Pull down to refresh.', K.W / 2, y + 8, 'footnote', K.C.text3, { align: 'center' });
    app.homeH = y + viewY + 40 + K.safe.bottom;    // measured this frame, used by K.scroll next frame
  });
  drawSpinner(app.pullDrop);
  const hit = K.navBar(PAGE_TITLE, viewY, { sub, right: { id: 'settings', icon: 'settings' } });
  if (hit === 'settings') app.sheet = 'settings';
  drawSettingsSheet();                             // sheets LAST, so nothing paints over them
}

// Hero: the one big number of the screen, its delta for the chosen range, the chart and the range control.
function drawHeroCard(x, y, w) {
  const h = 318, r = RANGES[prefs.range], series = portfolioSeries(r.key), held = ASSETS.filter((a) => a.held > 0);
  const value = held.every((a) => a.known) ? held.reduce((t, a) => t + a.price * a.held, 0) : null;
  const d = series ? seriesDelta(series) : null, col = !d || d.abs >= 0 ? GAIN : LOSS;
  const e = K.since(app.bootAt, 0, 500);           // launch entrance, counted from app.bootAt (Back does not replay it)
  enterGroup(e, () => {
    K.card(x, y, w, h);
    K.rect(x, y, w, h * 0.6, { r: K.R.l, grad: [K.alpha(ACCENT, 0.1), K.alpha(ACCENT, 0)] });   // soft blue sheen
    K.text(HERO_LABEL, x + 16, y + 32, 'label', K.C.text2);
    drawLiveStatus(x + w - 16, y + 28);
    if (!app.loaded) {                    // LOADING: shimmer exactly where the numbers will land
      K.shimmer(x + 16, y + 50, 220, 38, 10);
      K.shimmer(x + 16, y + 100, 170, 24, 12);
      K.shimmer(x + 16, y + 144, w - 32, 100, 12);
    } else {
      // Fit the hero number to its card: a seven-figure value at 40 px would overflow a narrow phone.
      const heroStr = value == null ? '–' : K.fmt.money(K.count('hero', value, 900));
      const heroSize = Math.min(40, 40 * (w - 32) / K.measureNum(heroStr, 'display', { size: 40 }));
      K.num(heroStr, x + 16, y + 84, 'display', K.C.text, { size: heroSize });
      if (d) {
        const label = signedMoney(K.count('heroDelta', d.abs, 700)) + ' (' + K.fmt.pct(d.pct) + ')';
        const cw = K.chip(x + 16, y + 98, label, { color: col, icon: d.abs >= 0 ? 'arrowUp' : 'arrowDown' });
        K.text(r.caption, x + 26 + cw, y + 110.5, 'footnote', K.C.text2, { base: 'middle' });
      } else K.text(value == null ? 'Waiting for the first live price' : 'No change known for this range', x + 16, y + 110.5, 'footnote', K.C.text2, { base: 'middle' });
      drawChart(series, { x: x + 16, y: y + 144, w: w - 32, h: 100 }, col, -1, false, noLine(held, r.key));
    }
  });
  // A kit control never goes inside enterGroup's transform: it takes { alpha } and the lifted y itself.
  K.inert(!reachable(y + 264, 34), () => {
    const idx = K.segmented('range', x + 16, y + 264 + lift(e), w - 32, RANGES.map(q => q.label), prefs.range, { alpha: e });
    if (idx !== prefs.range) setRange(idx);
  });
  return y + h;
}

// LIVE dot + wall-clock stamp (K.fmt.time takes Date.now() values, never millis()).
function drawLiveStatus(xr, cy) {
  const off = !!app.error, working = app.refreshing && app.mode !== 'tick';
  const label = off ? 'Offline' : working ? 'Updating…' : app.live ? 'Updated ' + K.fmt.time(app.updatedAt)
    : app.updatedAt ? 'Prices from ' + stamp(app.updatedAt) : ASSETS.some((a) => a.cg) ? 'Waiting for prices' : 'Your numbers';
  const col = off ? LOSS : ACCENT;
  const tw = K.text(label, xr, cy, 'caption', off ? LOSS : K.C.text2, { align: 'right', base: 'middle' });
  K.circle(xr - tw - 10, cy, 4 + 4 * K.pulse(4), { fill: K.alpha(col, 0.28) });
  K.circle(xr - tw - 10, cy, 3.5, { fill: col });
}

// ERROR state: a banner that grows in above the hero, shakes on each failure and offers Retry.
function drawErrorBanner(x, y, w) {
  const k = K.anim('banner', app.error ? 1 : 0, 10);
  if (k < 0.01) return y;
  const age = K.t - app.errorKick, wob = Math.sin(age * 38) * 10 * Math.max(0, 1 - age / 0.45);
  enterGroup(k, () => {
    K.card(x + wob, y, w, 72, { fill: K.mix(K.C.surface, LOSS, 0.1), stroke: K.alpha(LOSS, 0.35) });
    K.circle(x + wob + 34, y + 36, 18, { fill: K.alpha(LOSS, 0.16) });
    K.icon('alert', x + wob + 34, y + 36, 18, LOSS, { weight: 2.2 });
    K.text('You\'re offline', x + wob + 64, y + 32, 'headline', K.C.text);
    const since = app.updatedAt ? 'Prices from ' + stamp(app.updatedAt) : 'No live prices yet';
    K.text(since, x + wob + 64, y + 52, 'footnote', K.C.text2);
  });
  K.inert(!reachable(y + 20, 32), () => {
    if (K.button('retry', x + w - 86 + wob, y + 20 + lift(k), 70, 32, 'Retry', { style: 'tinted', color: LOSS, alpha: k })) refreshData('pull');
  });
  return y + 84 * k;
}

// ===== WATCHLIST ROWS =====
function drawAssetSection(title, list, y, order) {
  y = sectionLabel(title, list.length ? list.length + (list.length === 1 ? ' market' : ' markets') : '', y);
  const x = SIDE, w = K.W - 2 * SIDE, e = K.since(app.bootAt, order * 70, 500);
  if (!list.length) {                     // EMPTY state: explain how to fill it
    enterGroup(e, () => {
      K.card(x, y, w, 184);
      K.empty(K.W / 2, y + 8, 'star', 'No favourites yet', 'Open any market below and tap the star to pin it here.');
    });
    return y + 184;
  }
  const h = list.length * ROW_H;
  enterGroup(e, () => {
    K.card(x, y, w, h);
    K.clip(x, y, w, h, () => {
      list.forEach((a, i) => drawAssetRow(a, x, y + i * ROW_H, w, i, i < list.length - 1));
    }, K.R.l);
  });
  return y + h;
}

// One row: brand badge, ticker + name, mini sparkline, price (rolls + flashes on change), delta pill.
function drawAssetRow(a, x, y, w, i, divider) {
  const id = 'row:' + a.sym;
  K.inert(!reachable(y, ROW_H), () => {          // hidden rows: no taps, not in the tester's map
    const pressed = K.anim(id, K.holdIn(x, y, w, ROW_H) ? 1 : 0, 24);
    if (pressed > 0.01) K.rect(x, y, w, ROW_H, { r: 0, fill: K.alpha(K.C.text, 0.06 * pressed) });
    K.registerControl(id, x, y, w, ROW_H);      // custom hit area: register it every frame it is shown
    const tap = K.tapIn(x, y, w, ROW_H);
    if (tap) openDetail(a.sym, tap);
  });
  drawBadge(a, x + 36, y + ROW_H / 2, 20);
  K.text(a.sym, x + 68, y + 31, 'headline', K.C.text);
  if (prefs.alerts[a.sym]) K.icon('bell', x + 80 + K.measure(a.sym, 'headline'), y + 26, 13, GOLD, { weight: 2.2 });
  K.text(a.name, x + 68, y + 50, 'footnote', K.C.text2, { maxW: 88 });
  const right = x + w - 16;
  if (busy()) {                           // LOADING: keep the identity, shimmer the numbers
    K.shimmer(right - 176, y + 20, 64, 28, 6);
    K.shimmer(right - 92, y + 16, 92, 18, 6);
    K.shimmer(right - 68, y + 40, 68, 18, 8);
  } else {
    const s = a.series.D, d = s ? seriesDelta(s) : null, col = !d || d.abs >= 0 ? GAIN : LOSS;
    const e = K.since(app.dataAt, i * 70, 500), dx = 24 * (1 - e);   // fresh data slides in (app.dataAt = K.t on arrival)
    withAlpha(e, () => {
      if (lined(s)) K.spark(s, right - 176 + dx, y + 20, 64, 28, { color: col, dot: false, width: 1.8, t: e });
      const txt = a.known ? K.fmt.money(K.count('rowpx:' + a.sym, a.price, 600), CUR, dp(a.price)) : '–';
      // TICK FLASH: the number turns green / red when it changes, then fades back to white over 1.2 s.
      const flash = Math.max(0, 1 - (K.t - a.flashAt) / 1.2);
      const pxCol = flash > 0 ? K.mix(K.C.text, a.flashUp ? GAIN : LOSS, flash) : K.C.text;
      K.num(txt, right + dx, y + 30, 'headline', pxCol, { align: 'right' });
      if (d) drawDeltaPill(right + dx, y + 38, d, col);
    });
  }
  if (divider) K.line(x + 68, y + ROW_H, x + w, y + ROW_H, K.C.line, 1);
}

function drawBadge(a, cx, cy, r) {
  K.circle(cx, cy, r, { fill: K.alpha(a.color, 0.16) });
  K.circle(cx, cy, r - 0.5, { fill: 'none', stroke: K.alpha(a.color, 0.5), sw: 1.2 });
  K.text(a.glyph, cx, cy + 1, 'headline', a.color, { align: 'center', base: 'middle', weight: 800 });
}

// Fixed-minimum width pill, right-aligned, so every row's column lines up.
function drawDeltaPill(xr, y, d, col) {
  const label = prefs.showAmount ? signedMoney(d.abs) : K.fmt.pct(d.pct);
  const w = Math.max(68, K.measure(label, 'caption', { weight: 700 }) + 16);
  K.rect(xr - w, y, w, 21, { r: 7, fill: K.alpha(col, 0.16) });
  K.text(label, xr - w / 2, y + 11, 'caption', col, { align: 'center', base: 'middle', weight: 700 });
}

// ===== STAT GRID (Markets and Detail) =====
// stats: [{ label, value, sub, tone: 'up' | 'down' | '', icon }]. Two columns; returns the y below the grid.
function drawStatGrid(stats, x, y, w, enter, loading) {
  const cw = (w - GAP) / 2;
  stats.forEach((s, i) => {
    const cx = x + (i % 2) * (cw + GAP), cy = y + Math.floor(i / 2) * (STAT_H + GAP);
    const tint = s.tone === 'up' ? GAIN : s.tone === 'down' ? LOSS : ACCENT;
    enterGroup(enter(i), () => {
      K.card(cx, cy, cw, STAT_H, { r: 16 });
      K.circle(cx + cw - 26, cy + 26, 14, { fill: K.alpha(tint, 0.16) });
      K.icon(s.icon, cx + cw - 26, cy + 26, 15, tint, { weight: 2.2 });
      K.text(s.label, cx + 16, cy + 30, 'label', K.C.text3, { maxW: cw - 60 });
      if (loading) K.shimmer(cx + 16, cy + 44, cw * 0.55, 22, 6);
      else K.num(s.value, cx + 16, cy + 63, 'title3', K.C.text);
      K.text(s.sub, cx + 16, cy + 82, 'footnote', s.tone ? tint : K.C.text3, { maxW: cw - 32 });
    });
  });
  return y + Math.ceil(stats.length / 2) * (STAT_H + GAP) - GAP;
}

// ===== SCREEN: DETAIL =====
function drawDetail() {
  const a = assetBySym(app.sym), r = RANGES[prefs.range], series = a.series[r.key];
  const watched = prefs.watch.includes(a.sym), sub = a.sym + ' · ' + a.kind;
  K.backdrop({ top: '#0b1630', bottom: '#050a15', vignette: 0.4, grain: 0.04, glow: [
    { x: K.W * 0.1, y: 60, r: 340, color: a.color, s: 0.15 },      // each market tints its own page
    { x: K.W, y: 460, r: 300, color: ACCENT, s: 0.1 }] });
  app.detailY = K.scroll('detail', 0, 0, K.W, K.H, app.detailH);
  const sy = app.detailY;
  pageClip(() => {
    let y = K.navBar.top(sub) - sy;
    y = drawPriceHeader(a, series, r, y);
    y = drawChartCard(a, series, SIDE, y, K.W - 2 * SIDE) + 28;
    y = sectionLabel('STATS', a.sym, y);
    y = drawStatGrid(assetStats(a), SIDE, y, K.W - 2 * SIDE, i => K.stagger(i + 2, 60, 460), false) + 28;
    y = drawAbout(a, y) + 24;
    y = drawAlertButton(a, y);
    app.detailH = y + sy + 40 + K.safe.bottom;
  });
  const hit = K.navBar(a.name, sy, { sub,
    left: { id: 'back', icon: 'chevronLeft', label: PAGE_TITLE },
    right: { id: 'star', icon: 'star', color: watched ? GOLD : K.C.text2 } });
  // Saved: the kit's filled star over the bar's outline star (its 34 px button at K.W - 30 has a 17 px icon), springing in.
  if (watched) K.icon('star', K.W - 30, K.safe.top + 25, 17 * app.starSpring.v, GOLD, { fill: true });
  if (hit === 'back' || swipedBack()) goBack();
  if (hit === 'star') toggleWatch(a);
  drawAlertSheet(a);                               // sheets LAST
}

// Big price (or the scrubbed point's price), delta chip for the range, alert chip on the right.
function drawPriceHeader(a, series, r, y) {
  const scrub = app.scrubI >= 0 && lined(series), i = scrub ? Math.min(app.scrubI, series.length - 1) : series ? series.length - 1 : -1;
  const d = series ? seriesDelta(series, i) : null, col = !d || d.abs >= 0 ? GAIN : LOSS;
  const price = scrub ? series[i] : a.known ? K.count('dpx:' + a.sym, a.price, 700) : null;
  enterGroup(K.stagger(0, 60, 460), () => {
    K.num(price == null ? '–' : K.fmt.money(price, CUR, dp(price)), SIDE, y + 40, 'display', K.C.text, { size: 42 });
    if (d) {
      const label = signedMoney(d.abs) + ' (' + K.fmt.pct(d.pct) + ')';
      const cw = K.chip(SIDE, y + 54, label, { color: col, icon: d.abs >= 0 ? 'arrowUp' : 'arrowDown' });
      K.text(scrub ? pointLabel(a.times[r.key], r, i) : r.caption, SIDE + cw + 10, y + 66.5, 'footnote', K.C.text2, { base: 'middle' });
    } else K.text(a.known ? 'No change known for this range' : 'Waiting for the first live price', SIDE, y + 66.5, 'footnote', K.C.text2, { base: 'middle' });
    const alert = prefs.alerts[a.sym];
    if (alert) {
      const txt = K.fmt.money(alert, CUR, dp(alert));
      K.chip(K.W - SIDE - K.chipWidth(txt, { icon: 'bell' }), y + 54, txt, { color: GOLD, icon: 'bell' });
    }
  });
  return y + 96;
}

function drawChartCard(a, series, x, y, w) {
  const h = 280, col = !series || seriesDelta(series).abs >= 0 ? GAIN : LOSS, e = K.stagger(1, 60, 460);
  const plot = { x: x + 16, y: y + 48, w: w - 32, h: 160 };
  enterGroup(e, () => {
    K.card(x, y, w, h);
    K.text(RANGES[prefs.range].caption.toUpperCase(), x + 16, y + 28, 'label', K.C.text3);
    drawLiveStatus(x + w - 16, y + 24);
    K.inert(!reachable(plot.y, plot.h), () => {
      K.registerControl('chart', plot.x, plot.y, plot.w, plot.h);
      drawChart(series, plot, col, lined(series) ? updateScrub(plot, series) : (app.scrubI = -1), true, noLine([a], RANGES[prefs.range].key));
    });
  });
  K.inert(!reachable(y + h - 50, 34), () => {
    const idx = K.segmented('drange', x + 16, y + h - 50 + lift(e), w - 32, RANGES.map(q => q.label), prefs.range, { alpha: e });
    if (idx !== prefs.range) setRange(idx);
  });
  return y + h;
}

// ===== CHART =====
// Area chart with a dashed "start of range" line, high / low marks and an optional scrub cursor. Real points only: a range
// without them shows a short note instead of a line.
// We pass min / max to K.spark so our own overlay maths (yOf) matches its line exactly.
function drawChart(series, p, col, scrub, marks, note) {
  if (!lined(series)) { K.text(note || 'No chart for this range', p.x + p.w / 2, p.y + p.h / 2, 'footnote', K.C.text3, { align: 'center', base: 'middle' }); return; }
  const lo = Math.min(...series), hi = Math.max(...series), pad = (hi - lo) * 0.12 || 1;
  const yOf = v => p.y + p.h - ((v - (lo - pad)) / (hi - lo + 2 * pad)) * p.h;
  const xOf = i => p.x + (i / (series.length - 1)) * p.w;
  const t = K.since(app.chartAt, 0, 900);         // draw-on progress: 0.9 s from app.chartAt
  K.line(p.x, yOf(series[0]), p.x + p.w, yOf(series[0]), K.alpha(K.C.text, 0.22), 1, { dash: [2, 5] });
  K.spark(series, p.x, p.y, p.w, p.h, { color: col, t, min: lo - pad, max: hi + pad, dot: scrub < 0 });
  if (marks && t > 0.8) {
    const fade = (t - 0.8) / 0.2, iHi = series.indexOf(hi), iLo = series.indexOf(lo);
    const cx = i => K.clamp(xOf(i), p.x + 36, p.x + p.w - 36);
    K.text('H ' + K.fmt.money(hi, CUR, dp(hi)), cx(iHi), yOf(hi) - 10, 'caption', K.C.text2, { align: 'center', alpha: fade });
    K.text('L ' + K.fmt.money(lo, CUR, dp(lo)), cx(iLo), yOf(lo) + 20, 'caption', K.C.text2, { align: 'center', alpha: fade });
  }
  if (scrub >= 0) {
    const sx = xOf(scrub), sy = yOf(series[scrub]);
    K.line(sx, p.y - 4, sx, p.y + p.h, K.alpha(K.C.text, 0.35), 1);
    K.glow(sx, sy, 24, col, 0.5);
    K.circle(sx, sy, 5.5, { fill: col, stroke: K.C.surface, sw: 2.5 });
  }
}

// Chart scrubbing: hold still or drag sideways to read any point; a quick tap pins / unpins one.
// WHY claim the finger: once we own it, K.scroll will not also scroll the page with it.
function updateScrub(p, series) {
  let f = app.scrubId != null ? K.pointers.find(q => q.id === app.scrubId) : null;
  if (!f) {
    app.scrubId = null;
    const q = K.holdIn(p.x, p.y, p.w, p.h);
    const sideways = q && Math.abs(q.x - q.sx) > 6 && Math.abs(q.x - q.sx) > Math.abs(q.y - q.sy);
    const still = q && q.dist < 8 && performance.now() - q.t0 > 220;
    if (sideways || still) { q.claimed = 'scrub'; app.scrubId = q.id; app.pinI = -1; f = q; }
  }
  const tap = K.tapIn(p.x, p.y, p.w, p.h);
  if (tap) {
    app.pinI = app.pinI >= 0 ? -1 : indexAt(p, tap.x, series.length);
    K.sfx('tick');
    K.ring(tap.x, tap.y, { color: ACCENT, r1: 30 });
  }
  const i = f ? indexAt(p, f.x, series.length) : app.pinI;
  if (f && i !== app.scrubI) K.sfx('tick', { vol: 0.25 });
  app.scrubI = i;
  return i;
}

function indexAt(p, px, n) { return Math.round(K.clamp((px - p.x) / p.w, 0, 1) * (n - 1)); }

// The time a chart point stands for (CoinGecko's points are about an hour apart, so "about").
function pointLabel(times, r, i) {
  const ts = times && times[i] != null ? times[i] : Date.now();
  if (r.key === 'D') return 'about ' + K.fmt.time12(ts);
  return 'about ' + K.fmt.date(ts, { month: 'short', day: 'numeric' }) + ', ' + K.fmt.time12(ts);
}

// Detail stats: CoinGecko's own numbers ("–" when it sent none), so they re-compute after every refresh.
function assetStats(a) {
  const m = (v) => (v != null && v > 0 ? K.fmt.money(v, CUR, dp(v)) : '–');
  const vsNow = (v) => (v == null || !(v > 0) || !a.known ? (a.cg ? 'from CoinGecko' : 'not known')
    : Math.abs(v - a.price) < 0.005 ? 'Right now' : K.fmt.pct((v / a.price - 1) * 100) + ' vs now');
  return [
    { label: 'MARKET CAP', value: a.cap ? compactMoney(a.cap) : '–', sub: a.capNote || (a.cg ? 'from CoinGecko' : 'not known'), icon: 'globe' },
    { label: 'VOLUME 24H', value: a.volume ? compactMoney(a.volume) : '–', sub: 'Last 24 hours', icon: 'bolt' },
    { label: '24H HIGH', value: m(a.high), sub: vsNow(a.high), tone: a.high ? 'up' : '', icon: 'arrowUp' },
    { label: '24H LOW', value: m(a.low), sub: vsNow(a.low), tone: a.low ? 'down' : '', icon: 'arrowDown' },
    { label: 'ALL-TIME HIGH', value: m(a.ath), sub: vsNow(a.ath), icon: 'trophy' },
    { label: 'SUPPLY', value: a.supply ? K.fmt.compact(a.supply) : '–', sub: 'Coins in circulation', icon: 'coin' }
  ];
}

function drawAbout(a, y) {
  y = sectionLabel('ABOUT', a.kind, y);
  const w = K.W - 2 * SIDE, lines = K.wrap(a.about, w - 32, 'callout').length;
  const h = 24 + lines * 21.6;
  enterGroup(K.stagger(8, 60, 460), () => {
    K.card(SIDE, y, w, h);
    K.para(a.about, SIDE + 16, y + 10, w - 32, 'callout', K.C.text2);
  });
  return y + h;
}

function drawAlertButton(a, y) {
  const has = prefs.alerts[a.sym], e = K.stagger(9, 60, 460);
  const label = has ? 'Alert at ' + K.fmt.money(has, CUR, dp(has)) : 'Set price alert';
  K.inert(!reachable(y, 50), () => {
    if (K.button('alert', SIDE, y + lift(e), K.W - 2 * SIDE, 50, label, { icon: 'bell', style: has ? 'secondary' : 'primary', alpha: e })) openAlertSheet(a);
  });
  return y + 50;
}

// ===== ACTIONS =====
function openDetail(sym, tap) {
  app.sym = sym;
  app.chartAt = K.t + 0.2;                // start drawing the chart as the slide lands
  app.scrubI = -1; app.pinI = -1; app.scrubId = null;
  K.scrollTo('detail', 0);
  K.ring(tap.x, tap.y, { color: ACCENT, r1: 44 });
  K.sfx('select');
  K.go('detail', 'slide');
}

// Swipe right anywhere to go back. ONE path, by distance while the finger is still down: no time limit, so a slow,
// deliberate drag counts (K.swipe drops gestures over 1.3 s, and is NOT also read, so a swipe never moves twice).
// Fingers the chart scrub, the scroll or the slider claimed never count; we claim ours so nothing else reacts to it.
// K.isBlocked() = an open sheet, or the outgoing screen of a transition.
function swipedBack() {
  if (K.isBlocked()) return false;
  for (const p of K.pointers) {
    const dx = p.x - p.sx, dy = p.y - p.sy;
    if (!p.claimed && dx > 50 && dx > Math.abs(dy) * 1.3) { p.claimed = 'back'; return true; }
  }
  return false;
}

function goBack() {
  app.chartAt = K.t + 0.15;
  K.sfx('back');
  K.go('home', 'back');
}

function setRange(i) {
  prefs.range = i;
  app.chartAt = K.t;                      // the new series draws itself on
  app.pinI = -1;
  persist();
}

function toggleWatch(a) {
  const on = !prefs.watch.includes(a.sym);
  prefs.watch = on ? prefs.watch.concat(a.sym) : prefs.watch.filter(s => s !== a.sym);
  persist();
  const bx = K.W - 30, by = K.safe.top + 25;
  if (on) {
    app.starSpring.kick(14);
    K.burst(bx, by, { n: 16, shape: 'star', colors: [GOLD, '#ffffff'], speed: 260, gravity: 380, size: 7 });
    K.sfx('coin');
    K.toast(a.sym + ' added to Watchlist', { tone: 'good', icon: 'star' });
  } else {
    K.ring(bx, by, { color: K.C.text2, r1: 30 });
    K.sfx('back');
    K.toast(a.sym + ' removed from Watchlist', { icon: 'star' });
  }
}

function openAlertSheet(a) {
  if (!a.known) { K.toast('Waiting for a live price', { icon: 'clock' }); return; }
  const has = prefs.alerts[a.sym];
  app.alertDraft = has ? K.clamp(has / a.price - 1, -0.2, 0.2) : 0.05;
  app.sheet = 'alert';
}

function saveAlert(a, target) {
  prefs.alerts[a.sym] = target;
  persist();
  K.sfx('success');
  K.toast('Alert set at ' + K.fmt.money(target, CUR, dp(target)), { tone: 'good', icon: 'bell' });
  K.burst(K.W / 2, K.H - 140, { n: 22, shape: 'spark', colors: [GOLD, ACCENT, '#ffffff'], speed: 360, gravity: 0 });
}

function removeAlert(a) {
  delete prefs.alerts[a.sym];
  persist();
  K.sfx('back');
  K.toast('Alert removed', { icon: 'trash' });
}

// ===== SHEETS =====
// A button inside closes its sheet with close() (a backdrop tap or a swipe down closes it too); the line after
// K.sheet maps the kit's open flag back onto app.sheet, which names the one sheet that is open.
function drawSettingsSheet() {
  const open = K.sheet('settings', app.sheet === 'settings', 384 + K.safe.bottom, (x, y, w, h, close) => {
    K.text('Settings', 24, y + 48, 'title2', K.C.text);
    K.text(ASSETS.length + ' items · ' + (ASSETS.some((a) => a.cg) ? 'prices by CoinGecko' : 'your own numbers'), 24, y + 72, 'subhead', K.C.text2);
    K.card(16, y + 92, w - 32, 124, { fill: K.C.surface2, elev: 0 });
    const live = K.listRow('live', 16, y + 94, w - 32, 60,
      { title: 'Live updates', sub: 'Every ' + LIVE_EVERY_S + ' seconds', icon: 'bolt', iconColor: ACCENT, toggle: prefs.live }).toggle;
    K.line(74, y + 154, w - 16, y + 154, K.C.line, 1);
    // REPLACE: delete this test switch (and app.offline) in a real app; it only exists so the error state can be seen.
    const off = K.listRow('offline', 16, y + 154, w - 32, 60,
      { title: 'Simulate offline', sub: 'Test the error state', icon: 'alert', iconColor: LOSS, toggle: app.offline }).toggle;
    if (live !== prefs.live) {
      prefs.live = live;
      persist();
      K.toast(live ? 'Live updates on' : 'Live updates paused', { icon: live ? 'bolt' : 'pause' });
    }
    if (off !== app.offline) {
      app.offline = off;
      K.toast(off ? 'Offline: the next refresh will fail' : 'Connection restored', { tone: off ? 'warn' : 'good' });
    }
    K.text('SHOW CHANGE AS', 24, y + 246, 'label', K.C.text3);
    const seg = K.segmented('changeAs', 16, y + 258, w - 32, ['Percent', 'Amount'], prefs.showAmount ? 1 : 0);
    if (seg !== (prefs.showAmount ? 1 : 0)) { prefs.showAmount = seg === 1; persist(); }
    if (K.button('settingsDone', 16, y + 312, w - 32, 50, 'Done')) close();
  });
  if (!open && app.sheet === 'settings') app.sheet = null;
}

function drawAlertSheet(a) {
  const open = K.sheet('alert', app.sheet === 'alert', 392 + K.safe.bottom, (x, y, w, h, close) => {
    const target = Math.round(a.price * (1 + app.alertDraft) * 100) / 100;
    const col = app.alertDraft >= 0 ? GAIN : LOSS;
    K.text('Price alert', 24, y + 48, 'title2', K.C.text);
    K.text('Notify me when ' + a.name + ' crosses', 24, y + 72, 'subhead', K.C.text2);
    K.num(K.fmt.money(target, CUR, dp(target)), w / 2, y + 136, 'largeTitle', K.C.text, { align: 'center' });
    const chip = K.fmt.pct(app.alertDraft * 100, 1) + ' from now', icon = app.alertDraft >= 0 ? 'arrowUp' : 'arrowDown';
    K.chip(w / 2 - K.chipWidth(chip, { icon }) / 2, y + 152, chip, { color: col, icon });
    app.alertDraft = K.slider('alertPct', 32, y + 212, w - 64, app.alertDraft, -0.2, 0.2, { step: 0.005 });   // ticks as it moves
    K.text('-20%', 32, y + 246, 'caption', K.C.text3);
    K.text('Now', w / 2, y + 246, 'caption', K.C.text3, { align: 'center' });
    K.text('+20%', w - 32, y + 246, 'caption', K.C.text3, { align: 'right' });
    if (K.button('saveAlert', 24, y + 268, w - 48, 50, 'Save alert', { icon: 'bell' })) { saveAlert(a, target); close(); }
    if (prefs.alerts[a.sym]) {
      if (K.button('removeAlert', 24, y + 326, w - 48, 44, 'Remove alert', { style: 'ghost', color: LOSS, icon: 'trash' })) { removeAlert(a); close(); }
    } else if (K.button('cancelAlert', 24, y + 326, w - 48, 44, 'Cancel', { style: 'ghost' })) close();
  });
  if (!open && app.sheet === 'alert') app.sheet = null;
}

// ===== HELPERS =====
// Scrolled page content is drawn inside K.clip below the collapsed nav bar: rows never ghost through the
// (94 % opaque) bar, and kit hit tests (buttons, segmented, K.tapIn rows) only accept taps inside the clip.
function pageClip(fn) { const top = barBottom(); K.clip(0, top, K.W, K.H - top, fn); }

// WHY the fallback: K.navBar.barH is only set once the bar has drawn, and the bar draws after the content.
function barBottom() { return K.navBar.barH || K.safe.top + 50; }

// True when a hit area is fully visible: below the nav bar and above the bottom edge.
// WHY still needed with K.clip: a control clipped away (or half hidden) still shows up in the tester's controls
// map at its full size, so K.inert(!reachable(y, h), fn) takes it out of the map and out of reach.
function reachable(y, h) { return y >= barBottom() + 6 && y + h <= K.H - K.safe.bottom; }

// Fade + lift a whole group of DRAWING (card, text, chart, shimmer) as one; e = 0..1 entrance progress.
// Decoration only (K.spark / K.shimmer / K.para / K.empty take no alpha). Kit controls take { alpha: e } and
// y + lift(e) themselves, because kit hit areas ignore transforms.
function enterGroup(e, fn) { if (e > 0.001) withAlpha(e, fn, lift(e)); }
function lift(e) { return 18 * (1 - e); }

// Multiplies the opacity of everything drawn inside fn (shifted down by dy), on the kit's raw 2D context.
function withAlpha(a, fn, dy) { K.with(ctx => { if (dy) ctx.translate(0, dy); ctx.globalAlpha *= a; fn(); }); }

function sectionLabel(title, right, y) {
  K.text(title, SIDE + 4, y + 14, 'label', K.C.text2);
  if (right) K.text(right, K.W - SIDE - 4, y + 14, 'caption', K.C.text3, { align: 'right' });
  return y + 26;
}

function busy() { return !app.loaded || (app.refreshing && app.mode === 'pull'); }
function assetBySym(sym) { return ASSETS.find(a => a.sym === sym) || ASSETS[0]; }
function dp(v) { return Math.abs(v) < 1 ? 4 : 2; }
function signedMoney(n) { return (n >= 0 ? '+' : '-') + K.fmt.money(Math.abs(n)); }
function todayLabel() { return K.fmt.date(Date.now(), { weekday: 'long', month: 'long', day: 'numeric' }); }
// a time from today as HH:MM:SS; an older one with its date
function stamp(t) { return new Date(t).toDateString() === new Date().toDateString() ? K.fmt.time(t) : K.fmt.date(t, { month: 'short', day: 'numeric' }) + ' ' + K.fmt.time12(t); }

// WHY: K.fmt.compact stops at B, so trillions need their own tier ($1.34T, not $1340.6B).
function compactMoney(n) {
  if (Math.abs(n) >= 1e12) return CUR + (n / 1e12).toFixed(2) + 'T';
  return CUR + K.fmt.compact(n);
}
